4c\u4ee5\u4e0b\u6eaf\u6e90\uff1a\n\n1. **\u679a\u4e3e CLI**\uff1a`python -m <framework> ... --help | grep -iE 'zero.?bubble|pending|max-pending'`\u3002\n   - \u5206\u652f\u7532\uff08NVIDIA Megatron-LM \u98ce\u683c\uff09\uff1a\u5b58\u5728 `--max-pending-backward` \u4e0e `--zero-bubble-v-schedule` \u2192 \u8bbe `--max-pending-backward=2*pp` \u5e76\u5f00\u542f ZB \u76f8\u5173\u5f00\u5173\u3002\u82e5\u6846\u67b6\u53e6\u9700\u663e\u5f0f `--zero-bubble`/`--zero-bubble-v-schedule` \u5f00\u5173\uff0c\u6309\u5176\u6587\u6863\u3002\n   - \u5206\u652f\u4e59\uff08Pai/Megatron \u7cfb fork\uff09\uff1a\u5b58\u5728 `--zero-bubble-max-pending-backward` \u2192 \u76f4\u63a5\u8bbe\u503c `2*pp`\u3002\n   - \u5206\u652f\u4e19\uff1a\u4e24\u5206\u652f\u7686\u4e0d\u6ee1\u8db3\uff0c\u6216\u751f\u6210\u7684\u4e8b\u4ef6\u5e8f\u4e0e ZB-2p \u6a21\u677f\u4e0d\u7b26\uff08\u89c1\u7b2c 2 \u6b65\uff09\u2192 \u8bb0\u5f55\u5dee\u5f02\uff0c\u6539\u4ee5\u6846\u67b6*\u5b9e\u9645\u751f\u6210*\u7684\u8c03\u5ea6\u4e3a\u8bc4\u6d4b\u5bf9\u8c61\uff0c\u5e76**\u663e\u5f0f\u91cd\u547d\u540d\u8be5\u8c03\u5ea6**\uff08\u5982\"\u672c\u6846\u67b6 max-pending=2pp \u751f\u6210\u8c03\u5ea6\"\uff09\uff0c\u4e0d\u518d\u5ba3\u79f0\u5176\u4e3a\u8bba\u6587 ZB-2p\u3002\n2. **\u751f\u6210\u8c03\u5ea6\u6a21\u677f\u6bd4\u5bf9**\uff1adump \u5b9e\u9645\u751f\u6210\u7684\u4e8b\u4ef6\u5e8f\u5217\uff08(step, stage, microbatch, op \u7c7b\u578b F/BW/BI) \u5217\u8868\uff09\uff0c\u4e0e\u8bba\u6587/\u5df2\u77e5 ZB-2p \u6a21\u677f\uff08\u6216\u672c\u8bbe\u8ba1 \u00a78 \u6a21\u62df\u5668\u5185\u7f6e\u6a21\u677f\uff09\u9010\u4e8b\u4ef6\u6bd4\u5bf9\u3002\u6bd4\u5bf9\u7ed3\u679c\u4f5c\u4e3a\u4e00\u6761\u8bc1\u636e\u9644\u6863\u3002\n3. **bubble \u53e3\u5f84\u6838\u5bf9**\uff1a\u82e5\u6846\u67b6\u65e5\u5fd7\u81ea\u5e26\"bubble/\u5229\u7528\u7387\"\uff0c**\u4e0d\u5f97\u76f4\u63a5\u91c7\u4fe1**\u2014\u2014\u5728\u914d\u7f6e\u76f8\u540c\u7684\u4e00\u6b21\u8fd0\u884c\u91cc\u540c\u65f6\u53d6\u65e5\u5fd7\u6307\u6807\u4e0e\u6211\u4eec\u4ece trace \u81ea\u884c\u8ba1\u7b97\u7684\u6307\u6807\uff0c\u62a5\u544a\u4e24\u8005\u5dee\u5f02\uff1b\u5224\u5b9a\u4e00\u5f8b\u7528\u81ea\u884c\u8ba1\u7b97\u7684 S \u4e0e H\u3002\n\n**flag \u8bed\u4e49\u4e0d\u7b26\u65f6\u7684\u4fee\u6b63\u89c4\u5219**\uff1a\u4e0d\u7167\u642c\u9898\u8ff0\uff1b\u4ee5\u300c\u5206\u652f\u4e19\u8def\u5f84\u4e0b\u5b9e\u9645\u751f\u6210\u7684\u8c03\u5ea6\u300d\u91cd\u65b0\u8ba1\u7b97 S\u3001H\uff0c\u5e76\u5982\u5b9e\u62a5\u544a\u4e0e\u8bba\u6587 ZB-2p \u7684\u504f\u5dee\u53ca\u53ef\u80fd\u6210\u56e0\uff08\u5982\u751f\u6210\u5668\u7248\u672c\u5dee\u5f02\u3001\u7ea6\u675f\u4e0d\u540c\uff09\u3002\u6838\u5fc3\u4e3b\u5f20\u59cb\u7ec8\u6302\u9760\"\u5b9e\u9645\u751f\u6210\u7684\u4e8b\u4ef6\u5e8f\"\uff0c\u800c\u975e\u6302\u9760 flag \u540d\u6216\u8bba\u6587\u58f0\u79f0\u3002\n\n---\n\n## 3. \u5b9e\u9a8c\u914d\u7f6e\uff08\u4e3b\u5b9e\u9a8c + \u626b\u63cf\uff09\n\n**\u6a21\u578b**\uff1aGPT-\u98ce\u683c 1.3B \u2014\u2014 hidden=2048\u3001layers=24\u3001heads=16\u3001seq_len=1024\u3001vocab=50257\u3002\u7406\u7531\uff1a\u5c42\u6570\u53ef\u88ab pp\u2208{4,8,16} \u6574\u9664\uff08\u4fdd\u6301\u6bcf stage \u5c42\u6570\u76f8\u7b49\uff09\uff0c\u89c4\u6a21\u8db3\u591f\u8ba9 kernel \u65f6\u95f4\u53ef\u6d4b\u3001\u53c8\u8db3\u4ee5\u5728\u5355\u8282\u70b9 8\u00d7A100/H100 \u4e0a\u8dd1\u901a\u3002\u3010\u5047\u8bbeA2\uff1a24 \u5c42\u53ef\u6309 4/8/16 \u5747\u5206\uff0c\u6bcf stage 3/3/1.5 \u5c42\uff1bp=16 \u7528 24 \u5c42\u4f1a\u4e0d\u5747\u5206\uff0c\u6545 p=16 \u914d\u7f6e\u6539\u7528 hidden \u8f83\u5c0f/\u5c42\u6570 32 \u7684\u53d8\u4f53\u53e6\u884c\u8bf4\u660e\u3011\n\n**\u5e76\u884c\u62c6\u5206**\uff1aTP=1\u3001DP=1\u3001seq-parallel \u5173\uff08\u9694\u79bb\u6d41\u6c34\u7ebf\u6548\u5e94\uff0c\u6c14\u6ce1\u53ea\u6765\u81ea PP\uff09\u3002PP = \u6bcf stage \u4e00\u53f0 GPU\u3002\n\n**GPU**\uff08runbook \u76ee\u6807\u73af\u5883\uff09\uff1a\u540c\u578b\u53f7\u540c\u8282\u70b9\uff0cA100-80G \u6216 H100-80G\uff0cNVLink\uff08\u8282\u70b9\u5185\uff09+ \u540c\u4ea4\u6362\u673a\uff08\u8de8\u8282\u70b9\uff09\u3002\u914d\u7f6e\u77e9\u9635\u6240\u6709 cell \u7528\u540c\u4e00\u6279 GPU\u3002\n\n**\u4e3b\u5b9e\u9a8c**\uff1ap=8\uff0cmicrobatch_size=1\uff0cmicrobatch \u6570 m=16\uff08=2p\uff09\uff0c`overlap-p2p=on`\u3002\n\n**\u626b\u63cf\u7ef4\u5ea6\uff08\u654f\u611f\u6027\uff09**\uff1ap\u2208{4,8,16} \u00d7 m\u2208{2p,4p} \u00d7 overlap-p2p\u2208{on,off} \u00d7 \u8c03\u5ea6\u65cf\u2208{1F1B, ZB-1p, ZB-2p, ZB-V}\u3002\u6bcf cell \u56fa\u5b9a\u5176\u4f59\u5168\u90e8\u53d8\u91cf\u3002\n\n**\u8c03\u5ea6\u6fc0\u6d3b\u8868\uff08runbook \u4e2d\u7684\u7edf\u4e00\u6761\u76ee\uff09**\uff1a\n| \u8c03\u5ea6\u65cf | \u6fc0\u6d3b\u65b9\u5f0f | \u5907\u6ce8 |\n|---|---|---|\n| 1F1B | max_pending_backward=1\uff08\u6216\u6846\u67b6\u9ed8\u8ba4\uff09 | \u57fa\u7ebf |\n| ZB-1p | max_pending_backward=1 + ZB \u5f00\u5173 | \u4e2d\u95f4\u6863 |\n| ZB-2p | max_pending_backward=2p\uff08\u6309 \u00a72 \u5206\u652f\u9009\u62e9 flag\uff09 | \u4e3b\u76ee\u6807 |\n| ZB-V | `--zero-bubble-v-schedule`\uff08\u82e5\u53ef\u7528\uff09 | \u5907\u9009\u8fd1\u96f6\u65cf |\n\n---\n\n## 4. \u56fa\u5b9a\u53d8\u91cf\u4e0e\u5bf9\u7167\u7ec4\uff08\u63a7\u5236\uff09\n\n**\u56fa\u5b9a\uff08\u6240\u6709 cell \u76f8\u540c\uff09**\uff1a\u6a21\u578b\u67b6\u6784\u3001seq_len\u3001vocab\u3001microbatch_size=1\u3001\u68af\u5ea6\u7d2f\u79ef=m\uff08\u5373 microbatch \u6570\uff0c\u8de8 cell \u7edf\u4e00\u53e3\u5f84\uff09\u3001\u4f18\u5316\u5668 AdamW\uff08\u7edf\u4e00 \u03b2\u3001lr\u3001warmup\uff09\u3001\u7edf\u4e00 bf16\u3001`torch.use_deterministic_algorithms(True)` + cuDNN/cuBLAS \u786e\u5b9a\u6027\u3001\u6743\u91cd\u521d\u59cb\u5316\u4e0e\u6570\u636e shuffle \u968f\u673a\u79cd\u5b50\u3001\u540c\u6279 GPU \u4e0e\u4e92\u8054\u3001\u9884\u70ed/\u7a33\u6001\u53e3\u5f84\uff08\u00a76.1\uff09\u3001profile \u5f00\u5173\u4e0e\u5f00\u9500\u8865\u507f\uff08\u00a75\uff09\u3002\n\n**\u5bf9\u7167\u7ec4**\uff1a1F1B\uff08\u4e3b\u57fa\u7ebf\uff09\u3001ZB-1p\u3001ZB-V\uff08\u5982\u6846\u67b6\u652f\u6301\uff09\uff1b\u5168\u90e8\u4e0e ZB-2p \u9010\u914d\u7f6e\u5bf9\u9f50\u3002\n\n**p=16 \u5c42\u6570\u8bf4\u660e**\uff1a\u4e3b 24 \u5c42\u6a21\u578b\u4ec5\u7528\u4e8e p\u22648\uff1bp=16 \u4e13\u7528 32 \u5c42\u540c hidden \u53d8\u4f53\uff0c\u4f5c\u4e3a\u654f\u611f\u6027\u6570\u636e\u5355\u72ec\u6807\u6ce8\uff0c\u4e0d\u5e76\u5165 p\u22648 \u7ed3\u8bba\u3002\n\n---\n\n## 5. \u591a GPU \u5b9e\u6d4b\u65b9\u6cd5\uff08profiling\uff09\n\n- **\u6355\u83b7**\uff1a\u6bcf rank \u4e00\u4e2a `torch.profiler`\uff08`activities=[CUDA, CPU]`\uff0c`record_shapes=False` \u4ee5\u964d\u5f00\u9500\uff09\uff0c\u5305\u88f9 step \u5185\u5404 microbatch\u00d7op \u8ba1\u7b97\uff08F/BW/BI\uff09\u4e0e p2p \u901a\u4fe1\uff0c`on_trace_ready` \u5199\u51fa\u9010 rank chrome-trace/JSON\u3002\u5907\u9009\uff1ancu/nsys \u5728 1 \u6b21\u91cd\u590d\u4e2d\u4ea4\u53c9\u9a8c\u8bc1 kernel \u65f6\u95f4\u7cbe\u5ea6\u3002\n- **\u79bb\u7ebf\u5206\u6790\u811a\u672c**\uff1a\u9010 rank \u65f6\u95f4\u7ebf \u2192 \u6807\u8bb0\u6bcf kernel \u5c5e F/BW/BI/\u901a\u4fe1/\u5176\u4ed6 \u2192 \u8ba1\u7b97\u6bcf rank \u7684 busy \u65f6\u95f4\u3001\u7a7a\u95f2 gap\u3001step \u533a\u95f4\u3001S \u4e0e H\uff1b\u540c\u65f6\u4ece\u8c03\u5ea6\u5668 dump \u4e8b\u4ef6\u5e8f\u8ba1\u7b97 S \u5e76\u6bd4\u5bf9\u3002\n- **profile \u5f00\u9500\u63a7\u5236**\uff1a\u540c\u4e00 cell \u5f00/\u5173 profiler \u5404\u8dd1\u4e00\u6b21\uff0c\u6bd4\u8f83 wall-clock\uff1b\u82e5\u5f00\u542f\u6001\u4f7f step \u65f6\u957f\u504f\u5dee >2%\uff0c\u5219\u5728\u62a5\u544a\u4e2d\u8ba1\u5165\u8be5\u504f\u7f6e\u5e76\u8bf4\u660e\u5176\u8de8\u914d\u7f6e\u4e00\u81f4\u6027\uff08\u4e0d\u56e0\u914d\u7f6e\u4e0d\u540c\u800c\u6539\u53d8\u5224\u5b9a\uff09\u3002\u3010\u5047\u8bbeA3\uff1aprofile \u5f00\u9500\u53ef\u5ffd\u7565\u4e14\u8de8\u914d\u7f6e\u4e00\u81f4\u3011\n- **\u6d4b\u91cf\u6b21\u6570**\uff1a\u6bcf cell 5 \u7ec4\u968f\u673a\u79cd\u5b50 \u00d7 3 \u6b21\u91cd\u590d = 15 \u4e2a\u72ec\u7acb step-\u533a\u95f4\u6837\u672c\uff08\u5bf9\u786c\u4ef6\u5c42 H\uff09\u3002\u8c03\u5ea6\u5c42 S \u4e3a\u786e\u5b9a\u6027\u503c\uff0c\u7528 trace-replay + \u6a21\u677f\u53cc\u8def\u8ba1\u7b97\uff0c\u5404\u7ed9\u5355\u4e00\u6570\u503c + \u89e3\u6790\u6821\u9a8c\uff08\u00a78\uff09\u3002\n\n---\n\n## 6. \u5206\u6790\u8ba1\u5212\n\n### 6.1 \u7a33\u6001\u53e3\u5f84\n\u4e22\u5f03\u6bcf run \u524d 10% step \u4f5c\u9884\u70ed\uff1b\u53d6\u672b 20 \u4e2a\u7a33\u6001 step \u8ba1\u7b97\u6837\u672c\u3002\u7a33\u6001\u5224\u5b9a\uff1a\u672b 20 step \u7684\u6bcf step \u65f6\u957f CV<2%\u3002\n\n### 6.2 \u7edf\u8ba1\u6d41\u7a0b\n- \u6bcf cell\uff1a\u5bf9 15 \u4e2a\u6837\u672c\u8ba1\u7b97 \u03bc\u2095\u3001\u6807\u51c6\u5dee\u300195% CI\u3002CI \u7528 t \u533a\u95f4\uff08n=15\uff09\u4e0e bootstrap\uff08B=10\u2074\uff0c\u62a5\u544a BCa\uff09\u53cc\u8def\uff1b\u4e24\u8005\u4e0d\u4e00\u81f4\u65f6\u4ee5 bootstrap \u4e3a\u51c6\u5e76\u8bb0\u5f55\u3002\n- H3 \u7528**\u914d\u5bf9\u8bbe\u8ba1**\uff1a\u540c seed\u3001\u540c\u914d\u7f6e\u4e0b 1F1B \u4e0e ZB-2p \u7684\u9010 step \u7a7a\u95f2\u5dee\uff0cWilcoxon \u7b26\u53f7\u79e9\uff08\u5bf9\u79bb\u7fa4\u7a33\u5065\uff09\u4e3a\u4e3b\uff0c\u914d\u5bf9 t \u4e3a\u6b21\u3002\n- **\u9608\u503c\u5224\u5b9a**\uff08\u6240\u6709\u9608\u503c pre-registered\uff09\uff1aS_ZB2p\u22641%\uff1b\u03bc\u2095\u22642%\uff1b\u03bc\u2095+CI \u4e0a\u9650\u22645%\uff1b\u0394(H3) \u663e\u8457\u4e3a\u6b63\u3002\n- **\u89e3\u6790\u516c\u5f0f\u6821\u9a8c**\uff1a\u5bf9 1F1B\uff0c\u7a33\u6001\u4e14 m\u22652p\u22121 \u65f6\u9884\u671f S\u2248(p\u22121)/m\u3010\u89e3\u6790\u5173\u7cfb\uff0c\u8bba\u6587\u6807\u51c6\u7ed3\u679c\u3011\uff1b\u4ece trace-replay \u5f97\u5230\u7684 S \u82e5\u4e0e (p\u22121)/m \u504f\u5dee>\u8be5 cell \u8bef\u5dee\u5e26\uff0c\u5219\u544a\u8b66\u6392\u67e5\u3002ZB \u65cf\u65e0\u6b64\u95ed\u5408\u5f0f\u3010\u5047\u8bbeA4\uff1aZB-2p \u8c03\u5ea6\u5c42 S \u7531\u6a21\u62df\u5668\u7ed9\u51fa\u4e3a\u51c6\uff0c\u7406\u8bba\u8d8b\u52bf\"\u968f m \u589e\u5927\u8d8b 0\"\u4ec5\u4f5c\u65b9\u5411\u6027\u6821\u9a8c\u3011\u3002\n\n### 6.3 \u4e3b\u6b21\u6b21\u5e8f\uff08\u5224\u5b9a\u89c4\u5219\uff0c\u5148\u4e8e\u4e00\u5207\u5e73\u5747\uff09\n\u5224\u5b9a\u987a\u5e8f\u56fa\u5b9a\u4e3a\uff1a**L \u2192 S \u2192 H \u2192 \u0394**\uff0c\u4e0d\u5141\u8bb8\u8df3\u8fc7\u524d\u7f6e\u76f4\u63a5\u53d6\u5e73\u5747\u3002\n1. **\u68c0\u67e5 L**\uff1a\u8ba1\u7b97\u8de8 rank busy \u65f6\u95f4 CV\u3002\u5224\u4e3a\"\u8d1f\u8f7d\u5e73\u8861\u6210\u7acb\"\u5f53\u4e14\u4ec5\u5f53\uff1aCV\u22645% \u4e14 \u4efb\u4e00 rank \u5fd9\u65f6\u8ddd\u4e2d\u4f4d\u6570\u504f\u5dee\u22645%\u3010\u5047\u8bbeA5\uff1a\u6bcf stage \u7b49\u5c42\u6570\u5373\u8ba1\u7b97\u5747\u8861\u3011\u3002\n2. \u82e5 L \u4e0d\u6210\u7acb \u2192 **\u300c\u8fd1\u96f6\u300d\u7ed3\u8bba\u964d\u7ea7**\uff1a\u4e0d\u62a5\u544a\u5355\u4e00 \u03bc\u2095 \u5747\u503c\uff1b\u6539\u4e3a\u62a5\u544a\u9010 rank \u7a7a\u95f2\u5206\u5e03\u3001\u74f6\u9888 rank\uff08\u5fd9\u65f6\u6700\u5927\u8005\uff0c\u5176\u51b3\u5b9a step \u5468\u671f\uff09\u3001\u4ee5\u53ca\u4e0d\u5e73\u8861\u6765\u6e90\uff08p \u4e0d\u5747\u5206 / \u663e\u5b58\u538b\u529b\u81f4 memory-bound \u5c42\u53d8\u6162 / F\u2260B\uff09\u3002\u5224\u5b9a\u6539\u4e3a\"H \u5728\u74f6\u9888 rank \u4e0a\u662f\u5426 \u2264 \u9608\u503c\"\uff0c\u5e76\u5bf9\u6bcf\u4e00 rank \u5355\u72ec\u7ed9\u7ed3\u8bba\u4e0e\u89e3\u91ca\u3002\n3. \u4ec5\u5f53 L \u6210\u7acb\uff1a\u6309 \u00a76.2 \u5bf9 H1/H2/H3 \u9010\u6761\u5224\u5b9a\u3002\n\n### 6.4 F\u2260B \u65f6\u6b8b\u4f59\u6c14\u6ce1\u7684\u6765\u6e90\u4e0e\u68c0\u9a8c\uff08\u8865\u5145\u8981\u70b9 1\uff09\n- **\u6765\u6e90**\uff1aZB \u628a\u53cd\u5411\u62c6\u4e3a BW\uff08\u6743\u91cd\u68af\u5ea6\uff0c\u4f9d\u8d56\u672c\u5c42\u5df2\u5b58\u6fc0\u6d3b\u3001\u4e0d\u4f9d\u8d56\u4e0b\u6e38\uff09\u4e0e BI\uff08\u8f93\u5165\u68af\u5ea6\uff0c\u4f4d\u4e8e\u53cd\u5411\u5173\u952e\u94fe\uff09\u3002\u8fd1\u96f6\u8981\u6c42\u4e09\u6bb5\u65f6\u95f4\u53ef\u4e92\u586b\uff0c\u5373 **F\u3001BW\u3001BI \u4e09\u6bb5\u65f6\u957f\u57fa\u672c\u5e73\u8861**\uff0c\u4e14 F \u94fe\u4e0e BI \u94fe\u53ef\u4ea4\u53e0\u3001BW \u586b\u5145\u7a7a\u9699\u3002\u3010\u5047\u8bbeA6\uff1aGPT \u8bad\u7ec3\u4e2d\u8fd1\u4f3c\u6210\u7acb F\u2248BW\u2248BI\uff08\u5404\u7ea6\u5360 1/3 \u53cd\u5411+F \u603b\u91cf\uff09\u3011\n- **\u6b8b\u4f59\u6c14\u6ce1\u673a\u5236**\uff1a\u82e5 F\u65f6\u957f > BI\u65f6\u957f\uff08\u6216\u53cd\u4e4b\uff09\uff0c\u524d\u5411\u94fe\u4e0e\u53cd\u5411\u8f93\u5165\u94fe\u65e0\u6cd5\u5b8c\u7f8e\u4ea4\u53e0\uff0c\u672a\u88ab\u586b\u6ee1\u7684\u7a7a\u6321\u5373\u6b8b\u4f59\u6c14\u6ce1\uff1b\u82e5 BW \u8fc7\u5927\u585e\u4e0d\u8fdb\u7a7a\u9699\uff0c\u4ea6\u4ea7\u751f\u7a7a\u95f2\u3002\n- **\u68c0\u9a8c\uff08\u65e0\u9700 GPU\uff0c\u53ef\u786e\u5b9a\u6027\u5b8c\u6210\uff09**\uff1atrace-replay \u6a21\u62df\u5668\u7684**\u6270\u52a8\u6a21\u5f0f**\u2014\u2014\u4ee5\u5b9e\u6d4b\uff08\u6216\u4e00\u6b21\u79bb\u7ebf\u6d4b\u91cf\uff09\u7684\u6bcf op \u65f6\u957f T_F\u3001T_BW\u3001T_BI\uff0c\u6309\u6bd4\u4f8b\u7cfb\u6570 \u03bb\u2208[0.6,1.6] \u626b\u63cf T_F/T_BI\uff0c\u8f93\u51fa\u300c\u9884\u6d4b\u6b8b\u4f59\u6c14\u6ce1 vs \u4e0d\u5e73\u8861\u5ea6 \u03c1=T_F/T_B\u300d\u6807\u5b9a\u66f2\u7ebf\uff1b\u518d\u628a GPU \u5b9e\u6d4b\u7684\u6bcf rank \u03c1 \u4ee3\u5165\uff0c\u9a8c\u8bc1\u89c2\u6d4b H \u4e0e\u9884\u6d4b\u4e00\u81f4\uff08\u8bef\u5dee\u5e26\u5185\uff09\u3002\u82e5\u5b9e\u6d4b \u03c1 \u5904\u9884\u6d4b S>1%\uff0c\u5219\u8bf4\u660e\"\u8fd1\u96f6\"\u5728\u771f\u5b9e\u8d1f\u8f7d\u4e0b\u4e0d\u6210\u7acb\uff0c\u62a5\u544a\u5176\u503c\u800c\u975e\u9ed8\u8bb8\u3002\n\n---\n\n## 7. \u7ed3\u679c\u62a5\u544a\u6a21\u677f\uff08\u5224\u5b9a\u6811\u51fa\u53e3\uff09\n\u6bcf\u914d\u7f6e\u8f93\u51fa\u4e00\u5f20\u5361\u7247\uff1aS\uff08\u6a21\u62df\u5668/\u6a21\u677f\u53cc\u8def\uff09\u3001L\uff08CV \u4e0e\u901a\u8fc7\u4e0e\u5426\uff09\u3001\u03bc\u2095 \u4e0e CI\u3001H3 \u68c0\u9a8c p \u503c\u3001\u6b8b\u4f59\u6c14\u6ce1/\u03c1\u3001\u6846\u67b6 flag \u6838\u9a8c\u7ed3\u679c\uff08\u00a72 \u5206\u652f\u7532/\u4e59/\u4e19\uff09\u3001profile \u5f00\u9500\u504f\u5dee\u3002\u5361\u7247\u7684\u6700\u7ec8\u884c\u7531 \u00a76.3 \u5224\u5b9a\u6811\u51b3\u5b9a\uff08\"\u901a\u8fc7\u8fd1\u96f6\u5224\u5b9a\" \u6216 \"\u964d\u7ea7\uff1a\u74f6\u9888 rank=\u2026\uff0c\u7a7a\u95f2\u5206\u5e03=\u2026\uff0c\u539f\u56e0=\u2026\"\uff09\uff0c\u4e0d\u4f7f\u7528\u5355\u4e00\u5e73\u5747\u503c\u63a9\u76d6\u4e0d\u5e73\u8861\u3002\n\n---\n\n## 8. \u65e0 GPU \u73af\u5883\u4e0b\u7684\u53ef\u884c\u6027\u4e0e\u53ef\u590d\u73b0\u8def\u5f84\n\n- **trace-replay \u6a21\u62df\u5668\uff08\u7eaf Python 3.14\uff0c224-CPU \u53ef\u8dd1\uff0c\u4e0d\u4f9d\u8d56 torch/\u7f51\u7edc\uff09**\uff1a\u8f93\u5165 = (step, stage, microbatch, op \u7c7b\u578b, \u65f6\u957f) \u4e8b\u4ef6\u8868\uff1b\u8f93\u51fa\u6bcf stage \u7684 S \u4e0e\u6bcf\u65f6\u95f4\u69fd\u5360\u7528\u56fe\u3002\u4e8b\u4ef6\u8868\u6765\u6e90\uff1a\u2460 \u6846\u67b6 dump\uff08\u5f53\u771f\u5b9e\u6846\u67b6\u53ef\u7528\u65f6\uff09\uff1b\u2461 \u5185\u7f6e\u6a21\u677f\uff08\u8bba\u6587 ZB-2p/1F1B/ZB-V \u4e8b\u4ef6\u5e8f\uff09\u3002\u786e\u5b9a\u6027\uff1a\u540c\u4e00\u8f93\u5165 \u2192 \u540c\u4e00\u8f93\u51fa\uff0c\u53ef\u590d\u73b0\u3002\n- **\u6270\u52a8/\u6807\u5b9a\u6a21\u5f0f**\uff1a\u00a76.4 \u7684 F\u2260B \u6b8b\u4f59\u6c14\u6ce1\u66f2\u7ebf\u3001\u00a76.3 \u7684 rank \u4e0d\u5e73\u8861\u5f71\u54cd\uff0c\u5747\u53ef\u5728\u6b64\u6a21\u5f0f\u786e\u5b9a\u6027\u751f\u6210\u2014\u2014**\u6838\u5fc3\u8c03\u5ea6\u5c42\u7ed3\u8bba\uff08H1\u3001\u6b8b\u4f59\u6c14\u6ce1\u6765\u6e90\uff09\u65e0\u9700 GPU \u5373\u5f97**\u3002\n- **\u89e3\u6790\u6821\u9a8c**\uff1a1F1B \u7684 S\u2248(p\u22121)/m \u95ed\u5408\u5f0f\u4f5c\u4e3a\u6a21\u62df\u5668\u6b63\u786e\u6027\u6d4b\u8bd5\uff08\u00a76.2\uff09\u3002\n- **GPU \u90e8\u5206**\uff1a\u53ea\u4ea4\u4ed8 runbook\uff08\u00a72\u3001\u00a73\u3001\u00a75 \u7684\u9010\u6b65\u547d\u4ee4\u4e0e\u914d\u7f6e\u6837\u4f8b\uff09\u3001\u5224\u5b9a\u89c4\u5219\uff08\u00a76\uff09\u4e0e\u590d\u73b0\u8def\u5f84\uff0c\u4e0d\u5728\u6b64\u73af\u5883\u6267\u884c\u3002\n- **\u4ea4\u4ed8\u6e05\u5355**\uff1a\u2460 \u672